function searchMedicalIndex(query) {
  var q = String(query || '').toLowerCase().trim();
  if (!q) return [];

  function hasCjk(s) {
    return /[\u3400-\u9FFF]/.test(String(s || ''));
  }

  function withZhLabel(item) {
    if (hasCjk(item.label)) return item;
    var kws = item.keywords || [];
    for (var i = 0; i < kws.length; i++) {
      if (hasCjk(kws[i])) {
        return {
          keywords: item.keywords,
          page: item.page,
          hash: item.hash || '',
          label: kws[i]
        };
      }
    }
    return null;
  }

  var matched = (medicalSearchIndex || []).filter(function (item) {
    return (item.keywords || []).some(function (kw) {
      var k = String(kw).toLowerCase();
      return q.indexOf(k) !== -1 || k.indexOf(q) !== -1;
    });
  });

  var byKey = {};
  matched.forEach(function (item) {
    var zh = withZhLabel(item);
    if (!zh) return;
    var key = zh.page + '|' + zh.label;
    var prev = byKey[key];
    if (!prev) {
      byKey[key] = zh;
      return;
    }
    // Prefer the entry that deep-links to a section hash
    if (!(prev.hash) && zh.hash) byKey[key] = zh;
  });

  return Object.keys(byKey).map(function (k) { return byKey[k]; });
}
